#!/usr/bin/env python3
"""Decode a base64 string argument and write the decoded text to /workspace/comment.txt."""

import base64
import sys


def main() -> int:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <base64_string>", file=sys.stderr)
        return 1

    encoded = sys.argv[1]
    try:
        decoded_bytes = base64.b64decode(encoded, validate=True)
    except (ValueError, base64.binascii.Error) as exc:
        print(f"Error: invalid base64 input: {exc}", file=sys.stderr)
        return 1

    decoded_text = decoded_bytes.decode("utf-8")

    with open("/workspace/comment.txt", "w", encoding="utf-8") as f:
        f.write(decoded_text)

    return 0


if __name__ == "__main__":
    sys.exit(main())
